import { existsSync } from "node:fs";
import { join } from "node:path";

/**
 * Most posts declare an `image` in their frontmatter that was never added to public/.
 * Returns the public path only when the file actually exists.
 */
export function getExistingPostImage(image: string | undefined): string | null {
  if (!image || !image.startsWith("/")) return null;
  return existsSync(join(process.cwd(), "public", image)) ? image : null;
}

/**
 * Cover shown on blog cards and used as the share image: the post's own photo when it
 * exists, otherwise the cover generated by app/blog/[slug]/opengraph-image.tsx.
 */
export function getPostCoverUrl(post: { slug: string; image?: string }): string {
  return getExistingPostImage(post.image) ?? `/blog/${post.slug}/opengraph-image`;
}
